 static ushort[] Quad(ushort a,ushort b,ushort c,ushort d){return new ushort[]{a,b,c,d,65535,65535};}
 static ushort[] Closed(){return new ushort[]{65535,65535,65535,65535,65535,65535};}
 static byte[] Geometry(bool bend){
  NavigationTileQuantizedVertex[] vertices;NavigationTilePolygon[] polygons;var a=Closed();var b=Closed();var c=Closed();a[2]=1;b[0]=0;
  if(bend){b[1]=2;c[3]=1;vertices=new[]{V(0,0),V(0,1),V(2,1),V(2,0),V(3,1),V(3,0),V(2,3),V(3,3)};polygons=new[]{new NavigationTilePolygon(Quad(0,1,2,3),a),new NavigationTilePolygon(Quad(3,2,4,5),b),new NavigationTilePolygon(Quad(2,6,7,4),c)};}
  else{b[2]=2;c[0]=1;vertices=new[]{V(0,0),V(0,1),V(1,0),V(1,1),V(2,0),V(2,1),V(3,0),V(3,1)};polygons=new[]{new NavigationTilePolygon(Quad(0,1,3,2),a),new NavigationTilePolygon(Quad(2,3,5,4),b),new NavigationTilePolygon(Quad(4,5,7,6),c)};}
  var input=new NavigationTileDataInput(vertices,polygons,new byte[]{1,1,1},new ushort[]{1,1,1},new NavigationTileBounds(0,0,0,3,2,3),1,1,0,0,0,2,0.5f,1);var output=new NavigationTileDataOutput();var result=NavigationTileData.Build(input,output);Check(result.Outcome==NavigationTileDataOutcome.Published,"Actual owned geometry serialization: "+result.Detail);return output.Bytes;
